mapper.insert:
INSERT INTO prescription_item (prescription_id, drug_id, drug_name, specification, dosage, usage_method, frequency, days, quantity, unit_price, unit, remark) SELECT t.prescription_id, t.drug_id, t.drug_name, t.specification, t.dosage, t.usage_method, t.frequency, t.days, t.quantity, t.unit_price, t.unit, t.remark FROM (
SELECT #{item.prescriptionId} AS prescription_id, #{item.drugId} AS drug_id, #{item.drugName} AS drug_name, #{item.specification} AS specification, #{item.dosage} AS dosage, #{item.usageMethod} AS usage_method, #{item.frequency} AS frequency, #{item.days} AS days, #{item.quantity} AS quantity, #{item.unitPrice} AS unit_price, #{item.unit} AS unit, #{item.remark} AS remark FROM dual
) t
